  .toastify--bottom-right {
    bottom: 1em;
    right: 2em; }
  .toastify__img {
    float: left;
    margin-right: 8px;
    vertical-align: middle; }

.toastify__close {
  position: absolute;
  top: 0px;
  right: 2px;
  width: 16px;
  height: 16px;
  padding: 0;
  text-align: center;
  text-decoration: none;
  color: #aaa;
  font-weight: bold;
  font-size: 14px;
  background: transparent;
  outline: none;
  border: none;
  cursor: pointer;
  opacity: .5;
  transition: .3s ease; }
  .toastify__close:hover, .toastify__close:focus {
    opacity: 1;
    color: #000000; }

.toastify-content {
  position: relative;
  width: 100%;
  min-height: 62px;
  margin-bottom: 12px;
  padding: 8px;
  background: #ffffff;
